Local Ltac fit_zsizes :=
  repeat match goal with
  | |- context [Z.of_nat (cells_size ?cs)] =>
      let v := eval cbn [cells_size csize length Nat.add Z.of_nat Pos.of_succ_nat Pos.succ] in (Z.of_nat (cells_size cs)) in
